#include <iostream>
#include <string>
int main() {
    std::string input_buffer;
    std::cout << "Type some input and press Enter: ";
    // Read available characters without blocking
    std::streamsize available = std::cin.rdbuf()->in_avail();
    if (available > 0) {
        char* buffer = new char[available];
        std::streamsize read_chars = std::cin.readsome(buffer, available);
        std::cout << "Read " << read_chars << " characters: "
                  << std::string(buffer, read_chars) << std::endl;
        delete[] buffer;
    } else {
        std::cout << "No input available at this moment." << std::endl;
    }
    return 0;
}
